 @PutMapping("/committee-charters/{id}") public CharterResponse updateCharter(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody CharterInput i){req(SuccessionFoundationPermissionGuard.COMMITTEE,PrimeHrAction.EDIT,t);return service.updateCharter(agency.resolveAgencyId(a),id,i,c);}
